import{_ as i,o,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Version 2.0.0.2 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-2.0.0.2-released.md","filePath":"change-log/release/version-2.0.0.2-released.md"}'),a={name:"change-log/release/version-2.0.0.2-released.md"};function l(n,e,s,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="version-2-0-0-2-released" tabindex="-1">Version 2.0.0.2 Released <a class="header-anchor" href="#version-2-0-0-2-released" aria-label="Permalink to &quot;Version 2.0.0.2 Released&quot;">​</a></h1><h3 id="version-2-0-0-2-released-1" tabindex="-1">Version 2.0.0.2 Released <a class="header-anchor" href="#version-2-0-0-2-released-1" aria-label="Permalink to &quot;Version 2.0.0.2 Released&quot;">​</a></h3><p><strong>Date: 29th Mar 2026</strong></p><p><strong>Feature Release: Crypto Trading (Delta Exchange), RMoney Broker, Broker-Exchange Separation, Security Hardening &amp; Performance</strong></p><p>This is a feature release featuring <strong>158 commits</strong> (excluding auto-builds) from <strong>17 contributors</strong>, focused on full crypto trading support via Delta Exchange (24/7 markets, fractional quantities, leverage), RMoney broker integration, dynamic broker-exchange separation across all 31 brokers, comprehensive WebSocket FD audit (Phase 2) across 8 more streaming adapters, a 5x startup performance improvement, AliceBlue V3 and Flattrade V2 API upgrades, Zebu OAuth 2.0 migration, event bus architecture, and deep security hardening.</p><hr><p><strong>Highlights</strong></p><ul><li><strong>Crypto Trading (Delta Exchange)</strong> - Full cryptocurrency trading support with 24/7 market calendar, fractional quantities, leverage configuration, perpetual/options contracts, and crypto-aware UI across TradingView, GoCharting, Token Search, and Playground pages</li><li><strong>RMoney Broker Integration</strong> - Complete new broker integration including orders, WebSocket streaming, master contracts, funds, margins, multiquotes, and index symbol normalization</li><li><strong>Broker-Exchange Separation</strong> - Dynamic exchange capabilities per broker via <code>plugin.json</code> metadata for all 31 brokers, with frontend auto-adapting UI elements (product types, holdings, leverage) for stock vs crypto brokers</li><li><strong>Security Dashboard</strong> - New security dashboard with auto-ban toggle, table sorting, and IP management hardening</li><li><strong>Straddle PnL Simulator</strong> - New options analytical tool for simulating straddle profit/loss scenarios</li><li><strong>WebSocket FD Audit (Phase 2)</strong> - File descriptor leak fixes across 8 additional broker streaming adapters (Wisdom, iBulls, JainamXTS, IIFL, Compositedge, FivePaisaXTS, Mstock, Motilal)</li><li><strong>5x Startup Speedup</strong> - Reduced application startup time from 7–9s to ~1.6s via lazy imports, saving ~180MB RAM</li><li><strong>AliceBlue V3 &amp; Flattrade V2</strong> - Major broker API version upgrades</li><li><strong>Zebu OAuth 2.0 Migration</strong> - Migrated Zebu from TOTP login to OAuth 2.0 authentication</li><li><strong>Event Bus Architecture</strong> - Decoupled order side-effects via new event bus system with eventlet compatibility</li><li><strong>Deep Security Audits</strong> - 3 high-severity and 5 medium-severity findings patched, plus 6 CVE fixes</li></ul><hr><p><strong>New Features</strong></p><p><strong>Crypto Trading Support (Delta Exchange)</strong></p><ul><li>Full cryptocurrency trading with fractional spot quantities on Delta Exchange</li><li>24/7 market calendar system for crypto exchanges (no auto-logout)</li><li>Leverage configuration page for crypto brokers with validation</li><li>Broker capabilities API endpoint and frontend Zustand store</li><li>Dynamic exchange support via <code>supported_exchanges</code> in <code>plugin.json</code> for all 31 brokers</li><li>Wire <code>useSupportedExchanges</code> hook into all tools and WebSocket pages</li><li>Hide Holdings page and Product column for crypto brokers</li><li>Dynamic exchanges and product hiding for crypto on TradingView, GoCharting, and Token Search</li><li>Dynamic WebSocket presets for crypto in Playground</li><li>Crypto Bruno collection and broker-aware Playground loading</li><li>Subscribe to BTCUSDFUT for crypto option chain live underlying price</li><li>Conditionally show Leverage page for crypto brokers only</li><li>Add migration for <code>contract_value</code> column in symtoken table</li><li>Add CRYPTO to schema validations</li><li>Show combined spot+FNO wallet balance in INR for Delta Exchange</li></ul><p><strong>RMoney Broker Integration (New)</strong></p><ul><li>Complete broker integration from scratch — auth, order APIs, WebSocket streaming</li><li>Master contract download and data REST APIs</li><li>Funds API, Margin API, Multiquotes</li><li>Common NSE/BSE index symbol normalization</li><li>Added to all broker lists across install scripts and documentation</li></ul><p><strong>Straddle PnL Simulator</strong></p><ul><li>New Straddle PnL Simulator page (<code>/straddlepnl</code>) for options strategy analysis</li></ul><p><strong>Security Dashboard</strong></p><ul><li>Security dashboard with auto-ban toggle, table sorting, and hardening</li></ul><p><strong>Event Bus Architecture</strong></p><ul><li>Event bus for decoupled order side-effects (Telegram notifications, logging)</li><li>Resolve greenlet crash in event bus subscribers under eventlet</li></ul><p><strong>Infrastructure &amp; Deployment</strong></p><ul><li>Domain change script for existing server deployments</li><li>Update scripts for Linux and Windows</li><li>Add Delta Exchange broker to install scripts and documentation</li><li>Logout confirmation dialog warning about automated orders</li></ul><p><strong>Frontend Enhancements</strong></p><ul><li>Toast notifications for CSV export across all trading pages</li><li>CSV export respects active filters in OrderBook and TradeBook</li><li>Add MCX/CDS default underlyings to <code>useSupportedExchanges</code></li><li>Dynamic webhook URL based on TradingView alert mode</li></ul><hr><p><strong>Broker-Specific Changes</strong></p><p><strong>Delta Exchange (New Crypto Broker)</strong></p><ul><li>Full crypto trading support with fractional quantities for spot and derivatives</li><li>24/7 market calendar and auto-logout disabled</li><li>Leverage configuration with fractional rejection and retry on fetch error</li><li>Crypto perpetual symbol lookup and expiry support</li><li>Correct crypto exchange mapping, depth validation, and broker quotes</li><li>Source session P&amp;L from positions endpoint</li><li>Fix fractional spot quantity truncation in margin calculation</li><li>Safe-parse tradedQuantity and tradedPrice in tradebook transform</li><li>Filter orders and trades by current day</li><li>Cancel all orders includes GTC orders from prior days</li><li>Retry-on-transient-error for data API with read timeout support</li><li>Format Delta Exchange symbols to Tradeboard convention</li><li>Resolve correct perpetual underlying for crypto options</li></ul><p><strong>RMoney (New Broker Integration)</strong></p><ul><li>Complete implementation: auth, orders, WebSocket, funds, margins, multiquotes</li><li>Master contract download and data REST APIs</li><li>Common NSE/BSE index symbol normalization</li><li>Fix file descriptor leaks in XTS WebSocket streaming</li></ul><p><strong>Zebu</strong></p><ul><li>Migrate from TOTP login to OAuth 2.0 authentication</li><li>Fix MARKET order price handling and WebSocket disconnect deadlock</li><li>Fix order status, positions, MPP tick_size, and WebSocket stability</li><li>Resolve file descriptor leaks in WebSocket adapter</li></ul><p><strong>AliceBlue</strong></p><ul><li>Upgraded to V3 API</li><li>Fix WebSocket resource leaks, index historical data, and Funds realised PNL</li></ul><p><strong>Flattrade</strong></p><ul><li>Update to V2 API endpoints and WebSocket payload</li><li>Fix WebSocket auth ack type</li></ul><p><strong>Fyers</strong></p><ul><li>Fix rate limiting for Funds API</li><li>Correct <code>reformat_symbol_detail</code> day/year swap (DDMMMYY → correct format)</li><li>Add order, trade, and position data mapping and transformation utilities</li></ul><p><strong>Angel</strong></p><ul><li>Update base URL, add rate limit retry, and fix limit order price</li></ul><p><strong>Dhan</strong></p><ul><li>Sandbox API updated and added mocked WebSockets</li><li>Lazy-connect 20-depth WebSocket to preserve connection limit</li></ul><p><strong>Shoonya</strong></p><ul><li>Harden WebSocket streaming adapter (13-round FD audit)</li></ul><p><strong>Kotak</strong></p><ul><li>Harden WebSocket streaming adapter (9-round FD audit)</li></ul><p><strong>Groww</strong></p><ul><li>Make bulk insert atomic to prevent partial data on failure</li><li>Optimize master contract download and normalize streaming logs</li><li>Add common NSE/BSE index symbol mappings</li></ul><p><strong>Motilal</strong></p><ul><li>Add comprehensive NSE/BSE index symbol mappings</li><li>Fix WebSocket file descriptor leaks</li></ul><p><strong>Mstock</strong></p><ul><li>Fix WebSocket file descriptor leaks</li><li>Add common index symbol normalization</li></ul><p><strong>Compositedge</strong></p><ul><li>Common index symbol normalization</li><li>FD audit for streaming — prevent socket/thread leaks</li></ul><p><strong>XTS Brokers (FivePaisaXTS, iBulls, IIFL, JainamXTS, Wisdom)</strong></p><ul><li>Add index symbol normalization for all XTS brokers</li><li>FD audit for streaming adapters — prevent socket/thread leaks across all 5 brokers</li></ul><p><strong>Upstox</strong></p><ul><li>Handle position fetch failure in margin calculation</li></ul><p><strong>Multiple Brokers</strong></p><ul><li>Normalize tick_size from paise to rupees for Dhan, Firstock, Kotak, Nubra, Shoonya</li><li>Coerce order quantity to int for non-crypto brokers</li></ul><hr><p><strong>Bug Fixes</strong></p><p><strong>WebSocket &amp; Streaming</strong></p><ul><li>FD audit for 6 XTS broker streaming adapters (Wisdom, iBulls, JainamXTS, IIFL, Compositedge, FivePaisaXTS)</li><li>Harden Shoonya WebSocket streaming adapter (13-round FD audit)</li><li>Harden Kotak WebSocket streaming adapter (9-round FD audit)</li><li>Fix WebSocket file descriptor leaks for Mstock and Motilal</li><li>Fix WebSocket disconnect deadlock in Zebu adapter</li><li>Snapshot <code>self.ws</code> before <code>on_open</code> callback in <code>_handle_auth_response</code></li></ul><p><strong>Frontend &amp; UI</strong></p><ul><li>GoCharting page not showing API key on load</li><li>Handle invalid date in orderbook and tradebook for all brokers</li><li>Prevent strategy name overflow from hiding dropdown menu on Python Strategy page</li><li>Add optional chaining for holiday data in <code>useMarketStatus</code></li><li>Stale data warning banner never auto-dismisses (closes #1095)</li><li>Preserve user exchange selection during async capability sync</li><li>Fallback exchanges, leverage route guard, and async state sync</li><li>Clear stale capabilities on no-broker session</li><li>Use <code>makeFormatCurrency</code> in WebSocketTest instead of hardcoded broker check</li><li>Ensure CSV export respects active filters in OrderBook and TradeBook</li></ul><p><strong>Orders &amp; Positions</strong></p><ul><li>Use futures symbol for MCX/CDS LTP in optionsmultiorder</li><li>Prioritize explicit <code>expiry_date</code> and use futures symbol for MCX/CDS LTP</li><li>Optimize multi option Greeks to batch API calls (84 → 2)</li><li>Inject symbol/exchange keys into failed Greeks responses</li><li><code>get_first_available_api_key()</code> returns orphaned/revoked user keys</li><li>Coerce order quantity to int for non-crypto brokers</li></ul><p><strong>Backend &amp; Server</strong></p><ul><li>Pin gunicorn to 25.x and disable control socket</li><li>Replace bare except and silent exception handlers</li><li>Resolve greenlet crash in event bus subscribers under eventlet</li><li>Revert marshmallow to 3.x (4.x breaks schemas)</li><li>Revert llvmlite and pydantic-core to compatible versions</li><li>Make <code>/api/v1/telegram/notify</code> non-blocking by default</li><li>Prevent test-message endpoint from returning 500 on timeout</li><li>Fallback to plain text when Telegram Markdown parsing fails</li><li>Clean up <code>logs_session</code> in SecurityMiddleware for banned IP requests</li><li>Add graceful shutdown for strategy order processor queue</li><li>Guard ZMQ cleanup in <code>stop()</code> to prevent &quot;not a socket&quot; error on Ctrl+C</li><li>Force master contract re-download on broker change</li><li>Dynamic webhook URL based on TradingView alert mode</li><li>Correct 2026 market holiday calendar per official NSE/MCX circulars</li><li>Normalize tick_size from paise to rupees for 5 brokers</li><li>Remove duplicate code block causing IndentationError in brlogin.py</li></ul><hr><p><strong>Security</strong></p><ul><li>Patch 3 high-severity security findings from deep audit</li><li>Patch 5 medium-severity security findings from deep security audit</li><li>Patch 3 security vulnerabilities (CVE Dependabot #105, #106, #107)</li><li>Upgrade PyJWT to 2.12.0 (security fix)</li><li>Update requests 2.32.5 → 2.33.0 (security patch)</li><li>Patch npm vulnerabilities (socket.io-parser, picomatch)</li><li>Bump svgo 4.0.0 → 4.0.1 (CVE-2026-29074)</li><li>Bump tornado 6.5.4 → 6.5.5 (CVE-2025-47287)</li><li>Replace bare except and silent exception handlers across codebase</li><li>Security dashboard with auto-ban toggle and IP management</li></ul><hr><p><strong>Performance</strong></p><ul><li>Reduce startup time from 7–9s to ~1.6s (5x speedup)</li><li>Lazy-load heavy imports to reduce startup RAM by ~180MB</li><li>Lazy-load python-telegram-bot library to reduce startup RAM</li><li>Move startup logs to debug level to reduce log noise</li><li>Optimize multi option Greeks to batch API calls (84 → 2 requests)</li></ul><hr><p><strong>Refactoring &amp; Code Quality</strong></p><ul><li>Refactor code structure for improved readability and maintainability</li><li>Move Bruno collections to <code>IN_stock</code> subfolder</li><li>Add Google-style docstrings to utils module</li><li>Add type hints and docstrings to <code>security_middleware.py</code></li><li>Correct <code>check_tmp_noexec</code> return type annotation</li><li>Move <code>test_orphaned_apikey.py</code> to <code>test/</code> directory</li><li>Add missing file header comments to broker <code>funds.py</code> files</li><li>Add aria-label attributes to icon-only buttons for screen reader accessibility</li><li>Remove <code>frontend/dist</code> from version control (CI/CD builds it)</li></ul><hr><p><strong>Documentation</strong></p><ul><li>Rewrite CONTRIBUTING.md for React 19 + uv stack</li><li>Add incremental contribution policy to CONTRIBUTING.md</li><li>Allow new broker integrations as single PR in contribution policy</li><li>Update README to enhance description of Tradeboard and supported brokers</li><li>Update README YouTube video tutorial link</li><li>Broker-exchange separation audit for stock vs crypto UI</li><li>Crypto PR audit report for Delta Exchange integration</li></ul><hr><p><strong>Dependencies</strong></p><p><strong>Python</strong></p><ul><li>Bump the python-minor group with 22 updates + 13 additional updates</li><li>requests 2.32.5 → 2.33.0</li><li>PyJWT → 2.12.0</li><li>pytz 2025.2 → 2026.1.post1</li><li>bcrypt 4.1.3 → 5.0.0</li><li>cachetools 5.3.3 → 7.0.4</li><li>markdown-it-py 3.0.0 → 4.0.0</li><li>limits 3.13.0 → 5.8.0</li><li>flask-limiter 3.7.0 → 4.1.1</li><li>pyarrow 22.0.0 → 23.0.1</li><li>tornado 6.5.4 → 6.5.5</li><li>tradeboard 1.0.45 → 1.0.46</li><li>gunicorn pinned to 25.x</li><li>marshmallow 4.2.2 reverted to 3.x (compatibility)</li></ul><p><strong>Frontend</strong></p><ul><li>svgo 4.0.0 → 4.0.1</li><li>socket.io-parser security patch</li><li>picomatch security patch</li></ul><hr><p><strong>Contributors</strong></p><p>Special thanks to all contributors who made this release possible:</p><ul><li>@Kalaiviswa (kalaivani) — Crypto broker support, broker-exchange separation, WebSocket FD audits (Phase 2), security dashboard, leverage page, event bus</li><li>@rochronaldo (roch ronaldo) — RMoney broker integration</li><li>@BashabBhattacharjee (Bashab Bhattacharjee) — Delta Exchange crypto support, fractional quantities, Zebu OAuth 2.0 migration</li><li>@Sadhanandhann — Dhan sandbox API and mocked WebSockets</li><li>@GahanShetty (Gahan Shetty) — AliceBlue V3 upgrade</li><li>@sugatmankar — Groww index symbol mappings</li><li>@shubhamlodha21 — Flattrade WebSocket auth fix</li><li>@preet225 — Angel rate limiting and base URL fixes</li><li>@crypt0inf0 — Delta Exchange fixes</li><li>@Profesooor — Fyers symbol detail fix</li><li>@PratimaPrit — Accessibility improvements</li><li>@LuckyAnsari22 — Motilal index symbol mappings</li><li>@JaredW — Security middleware docstrings</li><li>@jagatsingh (Jagat Singh) — Dhan lazy WebSocket connect</li><li>@HirenThakore (Hiren Thakore) — RMoney XTS WebSocket FD fix</li><li>@DeepanshuGoyal (Deepanshu Goyal) — Aliceblue V3 Integration</li></ul><hr><hr><p><strong>Links</strong></p><ul><li><strong>Repository</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></li><li><strong>Documentation</strong>: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li><li><strong>Discord</strong>: <a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></li></ul><hr>',97)])])}const m=i(a,[["render",l]]);export{g as __pageData,m as default};
